import React, { useState, useEffect } from "react";
import { useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";
import "../Styles/UserProfile.css";

const UserProfile = () => {
  const navigate = useNavigate();
  const { user, isSuccess } = useSelector((state) => state.users); // ✅ من Redux بعد تسجيل الدخول
  const [cvFile, setCvFile] = useState(null);
  const [payment, setPayment] = useState(null);
  const [showEditInfo, setShowEditInfo] = useState(false);
  const [showEditPayment, setShowEditPayment] = useState(false);
  const [jobHistory, setJobHistory] = useState([]);

  // ✅ منع الدخول بدون تسجيل
  useEffect(() => {
    if (!isSuccess || !user?.email) {
      alert("⚠️ You must log in to view your profile.");
      navigate("/login");
    }
  }, [isSuccess, user, navigate]);

  // ✅ تحميل بيانات إضافية من MongoDB لاحقًا (اختياري)
  useEffect(() => {
    if (user) {
      // بإمكانك هنا لاحقًا تعمل طلب API مثل:
      // axios.get(`http://localhost:3001/userProfile/${user._id}`)
    }
  }, [user]);

  // ✅ Upload CV
  const handleUploadCV = (e) => {
    const file = e.target.files[0];
    if (file) {
      setCvFile(file);
      alert("CV uploaded successfully ✅");
    }
  };

  // ✅ Save Payment
  const handleSavePayment = (e) => {
    e.preventDefault();
    alert("Payment details saved ✅");
    setShowEditPayment(false);
  };

  if (!user) return <p style={{ textAlign: "center" }}>Loading user data...</p>;

  return (
    <div className="profile-page">
      {/* ----- Profile Header ----- */}
      <div className="profile-card">
        <div className="profile-left">
          <div className="profile-icon">👤</div>
          <div>
            <h2 className="profile-name">{user.name}</h2>
            <p className="profile-email">{user.email}</p>
            <p className="profile-detail">
              {user.major} • Age: {user.age} • {user.role}
            </p>

            {/* CV Section */}
            <div className="cv-section">
              <span className="cv-label">CV:</span>
              <label className="upload-btn">
                <input
                  type="file"
                  accept=".pdf,.doc,.docx"
                  onChange={handleUploadCV}
                  style={{ display: "none" }}
                />
                ⬆ Upload
              </label>
              {cvFile && <span className="cv-file">📄 {cvFile.name}</span>}
            </div>
          </div>
        </div>

        <button className="update-btn" onClick={() => setShowEditInfo(true)}>
          Update Info
        </button>
      </div>

      {/* ----- Applications Section ----- */}
      <div className="history-box">
        <h3>My Applications</h3>
        {jobHistory.length > 0 ? (
          jobHistory.map((job, index) => (
            <div key={index} className="job-item">
              <div>
                <h4>{job.title}</h4>
                <p>{job.company}</p>
              </div>
              <p
                className={`status ${job.status
                  ?.toLowerCase()
                  .replace(" ", "-")}`}
              >
                {job.status}
              </p>
            </div>
          ))
        ) : (
          <p>No applications yet.</p>
        )}
      </div>

      {/* ----- Payment Section ----- */}
      <div className="payment-box">
        <h3>Payment Details</h3>

        {!payment ? (
          <div>
            <p>
              No payment info yet. Add your payment details to receive payouts.
            </p>
            <button
              className="add-btn"
              onClick={() => setShowEditPayment(true)}
            >
              ➕ Add your Payment
            </button>
          </div>
        ) : (
          <div className="payment-info">
            <p>👤 Account Holder: {payment.accountHolder}</p>
            <p>🏦 Bank Name: {payment.bankName}</p>
            <p>💳 Account Number: {payment.accountNumber}</p>
            <p>🔢 IBAN: {payment.iban}</p>
            <div className="payment-actions">
              <button
                className="update-btn small"
                onClick={() => setShowEditPayment(true)}
              >
                ✏️ Edit Payment
              </button>
              <button
                className="delete-btn small"
                onClick={() => setPayment(null)}
              >
                🗑️ Delete
              </button>
            </div>
          </div>
        )}
      </div>

      {/* ----- Modal: Edit Info ----- */}
      {showEditInfo && (
        <div className="modal-overlay">
          <div className="modal-content">
            <h3>Edit Profile Info</h3>
            <form>
              <label>Full Name</label>
              <input type="text" defaultValue={user.name} />
              <label>Email</label>
              <input type="email" defaultValue={user.email} />
              <label>Major</label>
              <input type="text" defaultValue={user.major} />
              <label>Age</label>
              <input type="number" defaultValue={user.age} />
              <div className="modal-btns">
                <button type="submit" className="save-btn">
                  Save
                </button>
                <button
                  type="button"
                  className="cancel-btn"
                  onClick={() => setShowEditInfo(false)}
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ----- Modal: Add/Edit Payment ----- */}
      {showEditPayment && (
        <div className="modal-overlay">
          <div className="modal-content small">
            <h3>💳 {payment ? "Edit Payment Info" : "Add Your Payment"}</h3>
            <form onSubmit={handleSavePayment}>
              <label>Account Holder Name</label>
              <input type="text" placeholder="Aisha Ahmed" required />
              <label>Bank Name</label>
              <select required>
                <option value="">Select your bank</option>
                <option value="Bank Muscat">Bank Muscat</option>
                <option value="Bank Dhofar">Bank Dhofar</option>
                <option value="National Bank of Oman">
                  National Bank of Oman
                </option>
                <option value="Oman Arab Bank">Oman Arab Bank</option>
              </select>
              <label>IBAN</label>
              <input type="text" placeholder="OM84 0000 0000 1234..." />
              <label>Account Number</label>
              <input type="text" placeholder="1234567890" />
              <div className="modal-btns">
                <button type="submit" className="save-btn">
                  Save
                </button>
                <button
                  type="button"
                  className="cancel-btn"
                  onClick={() => setShowEditPayment(false)}
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default UserProfile;
